import { readFileSync } from 'fs';
import { join } from 'path';
import { describe, expect, it } from 'vitest';
import { darkVariant } from '../darkVariant';

// The CSS variables (generated by scripts/theme-hex-vars.py) and the runtime
// transform used for WebGL scenes must agree, or 3D scenes would drift from
// the 2D ones. Allow +-1 per channel for float rounding differences.
describe('darkVariant', () => {
  const css = readFileSync(join(__dirname, '../../../app/theme-hex.css'), 'utf8');
  const dark = css.slice(css.indexOf(':root[data-theme="dark"]'), css.indexOf('.theme-light'));
  const entries = [...dark.matchAll(/--h-([0-9a-f]{6}): (\d+) (\d+) (\d+);/g)];

  it('has dark variables to compare', () => {
    expect(entries.length).toBeGreaterThan(100);
  });

  it('matches every generated --h-xxxxxx dark value', () => {
    for (const [, hex, r, g, b] of entries) {
      const got = darkVariant(parseInt(hex, 16));
      expect(Math.abs(got[0] - +r), hex).toBeLessThanOrEqual(1);
      expect(Math.abs(got[1] - +g), hex).toBeLessThanOrEqual(1);
      expect(Math.abs(got[2] - +b), hex).toBeLessThanOrEqual(1);
    }
  });
});
